o=$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null); rc=$?
e=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null)
[ $rc = 2 ] && [ -z "$o" ] && [ "$e" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
o=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/dev/null); rc=$?
